{# ============================================================
   ITIHAD - PAYMENT ENTRY DISBURSEMENT
   ERPNext / Frappe v15
   Custom HTML + Jinja Print Format
============================================================ #}


{# ============================================================
   DATA
============================================================ #}

{% set arabic_amount = frappe.db.get_value(
    "Accounting Payment Entry",
    doc.name,
    "custom_amount_in_words_arabic"
) or "" %}

{% set usd_amount = doc.currency_totals
    | selectattr("currency", "equalto", "USD")
    | sum(attribute="total_debit") %}
{% set lbp_amount = doc.currency_totals
    | selectattr("currency", "equalto", "LBP")
    | sum(attribute="total_debit") %}


{# Donor Phone #}
{% set donor_phone = "" %}

{% if doc.donor %}
    {% set donor_phone = frappe.db.get_value(
        "Donor",
        doc.donor,
        "custom_phone_numper"
    ) or "" %}
{% endif %}


{# User / Receiver #}
{% set user = frappe.get_doc("User", doc.owner) %}


{# ============================================================
   GREGORIAN DATE
   Example:
   2026 / 8 / 25
============================================================ #}

{% set gregorian_year = "" %}
{% set gregorian_month = "" %}
{% set gregorian_day = "" %}

{% if doc.posting_date %}

    {% set gparts = (doc.posting_date|string).split("-") %}

    {% if gparts|length == 3 %}

        {% set gregorian_year = gparts[0] %}
        {% set gregorian_month = gparts[1]|int %}
        {% set gregorian_day = gparts[2]|int %}

    {% endif %}

{% endif %}


{# ============================================================
   HIJRI DATE

   Expected custom field:
   custom_hijri_date

   Supports:
   1448/3/12
   1448-3-12
   12/3/1448
============================================================ #}

{% set hijri_date = doc.get("custom_hijri_date") or "" %}

{% set hijri_year = "" %}
{% set hijri_month = "" %}
{% set hijri_day = "" %}


{% if hijri_date %}

    {% set hijri_clean =
        hijri_date|string
        |replace("-", "/")
        |replace("هـ", "")
        |replace("ه", "")
        |trim
    %}

    {% set hparts = hijri_clean.split("/") %}


    {% if hparts|length == 3 %}


        {# YYYY/MM/DD #}
        {% if (hparts[0]|int) > 1000 %}

            {% set hijri_year = hparts[0]|int %}
            {% set hijri_month = hparts[1]|int %}
            {% set hijri_day = hparts[2]|int %}


        {# DD/MM/YYYY #}
        {% else %}

            {% set hijri_day = hparts[0]|int %}
            {% set hijri_month = hparts[1]|int %}
            {% set hijri_year = hparts[2]|int %}

        {% endif %}


    {% endif %}

{% endif %}



<style>

/* ============================================================
   REMOVE FRAPPE DEFAULT HEADING
============================================================ */

.print-heading,
.print-heading h2,
.print-heading h3,
.print-heading small,
.page-header,
.page-header h2,
.page-header h3,
.page-header small {
    display: none !important;
}


/* ============================================================
   PRINT PAGE
============================================================ */

.print-format {
    margin: 0 !important;
    padding: 0 !important;
}


/* ============================================================
   MAIN RECEIPT
============================================================ */

.receipt {

    width: 100%;

    position: relative;

    margin: 0;
    padding: 0;

    box-sizing: border-box;

    direction: rtl;

    color: #111;

    /*
       Font selected to resemble the original Arabic receipt.
    */

    font-family:
        "Traditional Arabic",
        "Arabic Typesetting",
        "Simplified Arabic",
        Arial,
        sans-serif !important;

    font-size: 20px;

    line-height: 1.25;
}


.receipt * {

    font-family:
        "Traditional Arabic",
        "Arabic Typesetting",
        "Simplified Arabic",
        Arial,
        sans-serif !important;
}


.receipt-main {

    margin-right: 90px;

    padding: 0 8px 0 4px;

    box-sizing: border-box;
}


/* ============================================================
   LABELS
============================================================ */

.form-label {

    font-size: 21px;

    font-weight: 700;

    white-space: nowrap;

    vertical-align: bottom;
}


/* ============================================================
   DOTTED FIELDS
============================================================ */

.dotted-value {

    display: inline-block;

    border-bottom: 1.5px dotted #222;

    min-height: 26px;

    vertical-align: bottom;

    padding:

        0
        5px
        1px
        5px;

    margin: 0;

    box-sizing: border-box;

    font-size: 20px;

    font-weight: 400;

    line-height: 24px;
}


/* ============================================================
   RECEIPT TITLE
============================================================ */

.receipt-title {

    width: 73%;

    margin: 0 auto;

    background: #000;

    color: #fff;

    padding:
        4px
        8px
        6px
        8px;

    box-sizing: border-box;

    direction: rtl;

    text-align: center;

    font-size: 31px;

    font-weight: 700;

    line-height: 1.1;
}


/* ============================================================
   VERTICAL ORGANIZATION NAME
============================================================ */

.organization-box {

    position: absolute;

    top: 0;

    right: 0;

    width: 76px;

    height: 445px;

    background: #fff;

    border: 2px solid #111;

    box-sizing: border-box;

    overflow: hidden;
}


.organization-name {

    width: 100%;

    height: 100%;

    display: flex;

    align-items: center;

    justify-content: center;

    writing-mode: vertical-rl;

    transform: rotate(180deg);

    font-size: 24px;

    font-weight: 700;

    line-height: 1.25;

    color: #111;

    text-align: center;
}


/* ============================================================
   DATE
============================================================ */

.date-label {

    font-size: 20px;

    font-weight: 700;

    white-space: nowrap;
}


.date-value {

    font-size: 19px;

    font-weight: 500;

    white-space: nowrap;
}


/* ============================================================
   BOTTOM INFORMATION
============================================================ */

.bottom-title {

    font-size: 20px;

    font-weight: 700;

    line-height: 1.15;
}


.bottom-name {

    margin-top: 1px;

    font-size: 19px;

    font-weight: 600;

    line-height: 1.15;
}


/* ============================================================
   PRINT
============================================================ */

@media print {

    .print-heading,
    .page-header {
        display: none !important;
    }


    .print-format {

        margin: 0 !important;

        padding: 0 !important;
    }


    .receipt {

        page-break-inside: avoid !important;
    }

}

</style>



<div class="receipt" dir="rtl">


    <!-- =====================================================
         RIGHT VERTICAL ORGANIZATION NAME
    ====================================================== -->

    <div class="organization-box">

        <div class="organization-name">

            جمعية الاتحاد الإسلامي

        </div>

    </div>



    <!-- =====================================================
