{# ============================================================
   DATA
============================================================ #}

{% set arabic_amount = frappe.db.get_value(
    "Donation Entry",
    doc.name,
    "custom_amount_in_words_arabic"
) or "" %}

{% if doc.payments %}
    {% set usd_amount = doc.payments
        | selectattr("currency", "equalto", "USD")
        | sum(attribute="donation_amount") %}
    {% set lbp_amount = doc.payments
        | selectattr("currency", "equalto", "LBP")
        | sum(attribute="donation_amount") %}
{% else %}
    {% set usd_amount = doc.donation_amount if doc.currency == "USD" else 0 %}
    {% set lbp_amount = doc.donation_amount if doc.currency == "LBP" else 0 %}
{% endif %}


{# Donor Phone #}
{% set donor_phone = "" %}

{% if doc.donor %}
    {% set donor_phone = frappe.db.get_value(
        "Donor",
        doc.donor,
        "custom_phone_numper"
    ) or "" %}
{% endif %}


{# User / Receiver #}
{% set user = frappe.get_doc("User", doc.owner) %}


{# ============================================================
   GREGORIAN DATE
   Example:
   2026 / 8 / 25
============================================================ #}

{% set gregorian_year = "" %}
{% set gregorian_month = "" %}
{% set gregorian_day = "" %}

{% if doc.posting_date %}

    {% set gparts = (doc.posting_date|string).split("-") %}

    {% if gparts|length == 3 %}

        {% set gregorian_year = gparts[0] %}
        {% set gregorian_month = gparts[1]|int %}
        {% set gregorian_day = gparts[2]|int %}

    {% endif %}

{% endif %}


{# ============================================================
   HIJRI DATE

   Expected custom field:
   custom_hijri_date

   Supports:
   1448/3/12
   1448-3-12
   12/3/1448
============================================================ #}

{% set hijri_date = doc.get("custom_hijri_date") or "" %}

{% set hijri_year = "" %}
{% set hijri_month = "" %}
{% set hijri_day = "" %}


{% if hijri_date %}

    {% set hijri_clean =
        hijri_date|string
        |replace("-", "/")
        |replace("هـ", "")
        |replace("ه", "")
        |trim
    %}

    {% set hparts = hijri_clean.split("/") %}


    {% if hparts|length == 3 %}


        {# YYYY/MM/DD #}
        {% if (hparts[0]|int) > 1000 %}

            {% set hijri_year = hparts[0]|int %}
            {% set hijri_month = hparts[1]|int %}
            {% set hijri_day = hparts[2]|int %}


        {# DD/MM/YYYY #}
        {% else %}

            {% set hijri_day = hparts[0]|int %}
            {% set hijri_month = hparts[1]|int %}
            {% set hijri_year = hparts[2]|int %}

        {% endif %}


    {% endif %}

{% endif %}



